27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    public Boolean getBulkSignupWarning() {
140	        return this.bulkSignupWarning;
141	    }
142	
143	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
144	        this.bulkSignupWarning = bulkSignupWarning;
145	    }
146	
147	    public Integer getHouseholdSize() {
148	        return this.householdSize;
149	    }
150	
151	    public void setHouseholdSize(Integer householdSize) {
152	        this.householdSize = householdSize;
153	    }
154	
155	    /**
156	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
157	     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
158	     * Derived from the owner's own fields, so it stays consistent with them.
159	     */
160	    @Transient
161	    public String getMembershipNumber() {
162	        if (this.customerCode == null || this.registrationDate == null) {
163	            return null;
164	        }
165	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
166	    }
167	
168	    /**
169	     * The owner's membership tier: {@code "GOLD"} when the owner belongs to a household
170	     * of three or more members, otherwise {@code "SILVER"} for a unique owner (namesake
171	     * count of zero) who has an email on file, and {@code "BRONZE"} otherwise. Derived
172	     * from the owner's own fields, so it stays consistent with them.
173	     */
174	    @Transient
175	    public String getMembershipTier() {
176	        if (this.householdSize != null && this.householdSize >= 3) {
177	            return "GOLD";
178	        }
179	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
180	        boolean hasEmail = this.email != null && !this.email.isEmpty();
181	        return unique && hasEmail ? "SILVER" : "BRONZE";
182	    }
183	
184	    /**
185	     * The owner's locality: the canonical region derived from the city via the fixed
186	     * {@link CityRegionTable}, or {@code "UNKNOWN"} when the city is not in the table.
187	     * Derived from the owner's own city, so it stays consistent with it.
188	     */
189	    @Transient
190	    public String getLocality() {
191	        return CityRegionTable.regionFor(this.city);
192	    }
193	
194	    /**
195	     * Normalize the registration date before persisting: default it to the server's
196	     * current date when none was supplied, then roll it forward onto a business day so
197	     * every newly persisted owner is registered on a weekday.
198	     */
199	    @PrePersist
200	    void normalizeRegistrationDate() {
201	        if (this.registrationDate == null) {
202	            this.registrationDate = LocalDate.now();
203	        }
204	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
205	    }
206	
207	    protected Set<Pet> getPetsInternal() {
208	        if (this.pets == null) {
209	            this.pets = new HashSet<>();
210	        }
211	        return this.pets;
212	    }
213	
214	    protected void setPetsInternal(Set<Pet> pets) {
215	        this.pets = pets;
216	    }
217	
218	    public List<Pet> getPets() {
219	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
220	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
221	        return Collections.unmodifiableList(sortedPets);
222	    }
223	
224	    public void setPets(List<Pet> pets) {
225	        this.pets = new HashSet<>(pets);
226	    }
227	
228	    public void addPet(Pet pet) {
229	        getPetsInternal().add(pet);
230	        pet.setOwner(this);
231	    }
232	
233	    /**
234	     * Return the Pet with the given name, or null if none found for this Owner.
235	     *
236	     * @param name to test
237	     * @return true if pet name is already in use
238	     */
239	    public Pet getPet(String name) {
240	        return getPet(name, false);
241	    }
242	
243	    /**
244	     * Return the Pet with the given name, or null if none found for this Owner.
245	     *
246	     * @param name to test
247	     * @return true if pet name is already in use
248	     */
249	    public Pet getPet(String name, boolean ignoreNew) {
250	        name = name.toLowerCase();
251	        for (Pet pet : getPetsInternal()) {
252	            if (!ignoreNew || !pet.isNew()) {
253	                String compName = pet.getName();
254	                compName = compName.toLowerCase();
255	                if (compName.equals(name)) {
256	                    return pet;
257	                }
258	            }
259	        }
260	        return null;
261	    }
262	
263	    public Pet getPet(Integer petId) {
264	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
265	    }
266	
267	    @Override
268	    public String toString() {
269	        return new ToStringCreator(this)
270	
271	            .append("id", this.getId())
272	            .append("new", this.isNew())
273	            .append("lastName", this.getLastName())
274	            .append("firstName", this.getFirstName())
275	            .append("address", this.address)
276	            .append("city", this.city)
277	            .append("telephone", this.telephone)
278	            .toString();
279	    }
280	}
